import re,collections,datetime
t=open('products/research/paid-review-contests/sherlock-active-tab.html',encoding='utf-8',errors='replace').read()
u=t.replace('\\"','"')
print('len',len(t))
for m in re.finditer(r'"queryKey":\[[^\]]*\]',u): print('QK',m.group(0)[:200])
print(collections.Counter(re.findall(r'"status":"([A-Z_]+)"',u)))
for m in re.finditer(r'"total":(\d+),"hasNext":(true|false),"pages":(\d+)',u): print('PAGING',m.groups())
for m in re.finditer(r'"status":"(RUNNING|CREATED)"',u):
  s=u[max(0,m.start()-1500):m.end()+1500]
  print('CTX',re.findall(r'"(id|title|starts_at|ends_at|prize_pool|rewards|currency|private|short_description)":("[^"]{0,120}"|[0-9.]+|true|false)',s)[:30])
for ts in sorted(set(re.findall(r'"(?:starts_at|ends_at)":(\d{10})',u))): print('TS',ts,datetime.datetime.utcfromtimestamp(int(ts)).isoformat())
